def _read(p):
    with io.open(p, encoding="utf-8", newline="") as fh:
        return fh.read()


def _grab(txt, pat, what, flags=re.M):
    m = re.search(pat, txt, flags)
    if not m:
        raise SystemExit("⛔ 收据里核不到「%s」（模式 %s）" % (what, pat))
    return m


def _reg_facts():
    p = os.path.join(EV, "reg_24489.txt")
    if not os.path.isfile(p):
        raise SystemExit("⛔ 缺 R10 全回归收据：%s ⇒ ⇒ **不许**在没跑全回归的情况下写交接" % p)
    txt = _read(p)
    out = {}
    for key, pat in (("ledger_lines", r"ledger_lines=(\d+)"),
                     ("ledger_md5", r"ledger_md5=(\w+)"),
                     ("index_lines", r"index_lines=(\d+)"),
                     ("index_md5", r"index_md5=(\w+)"),
                     ("added", r"added=(\d+)"), ("removed", r"removed=(\d+)"),
                     ("n_exec", r"n_exec_py=(\d+)"), ("reg_rc", r"REG_RC=(\d+)"),
                     ("bad_n", r"BAD_n=(\d+)"), ("gate_rc", r"GATE_RC=(\d+)")):
        m = re.search(pat, txt)
        out[key] = m.group(1) if m else "(缺)"
    m = re.search(r"小结：变异台.*", txt)
    out["summary"] = m.group(0) if m else "(缺)"
    return out


